class UserTable extends Eloquent\Table {
    use User;

    protected $users = Eloquent\OneOf(Eloquent\Strings('user_id', 'username'));
    protected $usersCount = Eloquent\OneOf(0);

    @Eloquent\HasField('users')
    protected function get($row): array {
        return [
