            'phone' => $this->get('phone'),
            'date_of_birth' => $this->get('date_of_birth'),
            'gender' => $this->get('gender')
        ];
    }

    @Eloquent\HasField('usersCount')
    protected function getCount() : int {
        return $this->count('users');
    }
}
