   - Generate random integers between 1 and 6 for each die.
   - Record the sum of each roll.

4. **Compute Empirical Probabilities**
   - For each simulated roll, update the count for its respective sum.
   - Calculate the empirical probability by dividing the count by the total number of rolls.

5. **Organize Results in a Table**
   - Create a table listing each possible sum and its corresponding theoretical and empirical probabilities.
   - Format the table to ensure proper alignment and readability.

### Solution Code

```java
import java.util.ArrayList;
import java.util.List;

public class DiceSimulation {
    private static final int[] THEORETICALPROBABILITIES = {0.0278, 0.0556, 0.0833, 0.1111, 0.1389, 0.1667, 0.1667, 0.1389, 0.1111, 0.0833, 0.0556, 0.0278};

    private static final int[] EMPIRICALPROBABILITIES = new int[12];

    public static void main(String[] args) {
        List<String> results = new ArrayList<>();

        // Add header to the results list
        results.add("Sum\tTheoretical Probability\n");
        results.add("Empirical Probability\n");

        // Simulate 36 rolls
        simulateRolls(36, results);

        // Simulate 500 rolls
        simulateRolls(500, results);

        // Simulate 10,000 rolls
        simulateRolls(10000, results);

        // Print the results
        System.out.println("\nResults Summary:");
        for (String str : results) {
            System.out.println(str);
        }
    }

    private static void simulateRolls(int numRolls, List<String> results) {
        Random random = new Random();

        for (int i = 0; i < numRolls; i++) {
            int die1 = random.nextInt(6) + 1;
            int die2 = random.nextInt(6) + 1;
            int sum = die1 + die2;

            results.add(die1 + " | " + die2 + " | " + sum);

            if (results.size() > 1) {
                double prob = ((double) results.get(results.indexOf(sum)) + 1) / numRolls;
                EMPIRICALPROBABILITIES[sum - 2] = prob;
            } else {
                EMPIRICALPROBABILITIES[sum - 2] = 1.0 / numRolls;
            }
        }
    }

    private static class Random {
        private int seed = System.currentTimeMillis();

        private int nextInt(int n) {
            seed = (seed * 25214903917) + n;
            return seed % n;
        }
    }
}
```

