#include <vector>
#include <algorithm>

using namespace std;

int main() {
    vector<int> data = {5, 3, 8, 1, 7, 2, 9};

    // Step 1: Sort the data using Selection Sort
    sort(data.begin(), data.end());

    // Step 2: Build the BST
    struct Node {
        int key;
        Node* left;
        Node* right;

        Node(int key) : key(key), left(nullptr), right(nullptr) {}
    };

    Node* root = nullptr;
    for (int value : data) {
        Node* node = new Node(value);
        if (root != nullptr && node->key < root->key) {
            root = node;
        }
        node->left = nullptr;
        node->right = nullptr;
    }

    // Print the BST
    displayTree(root);
    cout << "\nRunning Time Analysis:\n";
    cout << "Time Complexity: O(n^2)\n";
    cout << "Explanation: Selection Sort has a time complexity of O(n^2), making it inefficient for large datasets.\n";

    return 0;
}

struct Node {
