    Node* left;
    Node* right;

    Node(int key) : key(key), left(nullptr), right(nullptr) {}
};

void displayTree(Node* node) {
    if (node == nullptr) {
        return;
    }

    displayTree(node->left);
    cout << "\n";
    cout << "Key: " << node->key << "\n";
    displayTree(node->right);
}
