// Define your feature collections
var admin = ee.FeatureCollection("FAO/GAUL/2015/level1");
var filter = ee.Filter.inList('ADM1_NAME', ['Jawa Timur']);
var jatim = admin.filter(filter);

// Set the map center coordinates
var ROI = jatim;
Map.setCenter(112.62, -7.96, 8);

// Create Landsat ImageCollection
var l8 = ee.ImageCollection("LANDSAT/LC08/C01/T1_TOA");

// Filter and clip the data
var l8 = l8.filterBounds(ROI)
    .filterDate("2015-01-01", "2015-12-31")
    .filterMetadata("CLOUD_COVER", "less_than", 1)
    .mean()
    .clip(ROI);

// Clip again to ensure data remains within ROI
var l8 = l8.clip(ROI);

// Merge utanSekunder and AreaTerbuka
var training_points = ee.DataSet.merge(utanSekunder, AreaTerbuka);

// Extract LC data
var training_data = training_points
    .sampleRegions({collection: training_points, properties: ["LC"]})
    .clip()

    .filterBounds(ROI)
    .filterDate("2015-01-01", "2015-12-31")
    .filterMetadata("CLOUD_COVER", "less_than", 1);

// Train the classifier
var classifier = ee.Classifier.smileCart();
var classifier = classifier.train({features: training_data, classProperty: "LC", inputProperties: ["B2", "B3", "B4", "B5", "B6", "B7", "B10", "B11']});

