   ```javascript
   const plotPoints = useCallback(() => {
     const canvas = useCanvas();
     const ctx = canvas.getContext('2d');

     let slope = 0;
     let intercept = 0;
     let isDragging = false;
     let lastPoint = null;

     const handleStart = (event) => {
       if (!isDragging) {
         isDragging = true;
         lastPoint = { x: 0, y: 0 };
         setPoints(prev => [...prev, { x: 0, y: 0 }]);
       }
     };

     const handleMove = (event) => {
       if (!isDragging) return;
       const rect = canvas.getBoundingClientRect();
       const x = event.clientX - rect.left;
       const y = event.clientY - rect.top;
       const dx = x - lastPoint.x;
       const dy = y - lastPoint.y;
       if (Math.abs(dx) > Math.abs(dy)) {
         slope = dy / dx;
         intercept = y - slope * x;
       } else {
         lastPoint = { ...lastPoint, x, y };
       }
       setPoints(prev => [...prev, { x: x, y: y }]);
       drawLine(slope, intercept);
     };

     function drawLine(slope, intercept) {
       ctx.beginPath();
       ctx.moveTo(lastPoint.x, lastPoint.y);
       for (let i = 1; i <= 100; i++) {
         const x = lastPoint.x + i * Math.cos(Math.PI * slope);
         const y = lastPoint.y + i * Math.sin(Math.PI * slope);
         ctx.lineTo(x, y);
       }
       ctx.strokeStyle = '#e74c3c';
       ctx.lineWidth = 2;
       ctx.stroke();
     }

     async function startDrawing() {
       await window.addEventListener('touchstart', handleStart);
       const container = document.querySelector('.container');
       container.style.cursor = 'grabbing';
       container.addEventListener('mousedown', startDrawing);
       container.addEventListener('mousemove', handleMove);
       container.addEventListener('mouseup', () => {
         startDrawing();
       });
     }
   }, [slope, intercept]);

   // Start Drawing
   startDrawing();
