```go
package main

import (
	"time"
)

const N = 5 // Number of assets
const M = 100 // Total budget percentage
type Solution struct {
	Weights []float // Asset weights
}

func NewPopulation(popSize int) *Solution {
	pop := make([]Solution, popSize)
	for i := 0; i < popSize; i++ {
	pop[i] = Solution{
			Weights: []float(time.Now().Unix() + float64(math.HalfNormal(5)) * 0.1),
		}
	}
	return pop
}

func Fitness(solution Solution) float64 {
	total := 0.0
	for w := range solution.Weights {
		if w < 0 || w > 1 {
			return 0.0
		}
		total += w
	}
	if total > M {
		return 0.0
	}
	return -total // Maximize total without exceeding budget
}

func ConstraintCheck(solution Solution) bool {
	for _, w := range solution.Weights {
		if w < 0 || w > 1 {
			return false
		}
	}
	return true
}

func InitializePopulation(popSize int) *Solution {
	pop := make([]Solution, popSize)
	for i := 0; i < popSize; i++ {
		pop[i] = Solution{
			Weights: []float(time.Now().Unix() + float64(math.HalfNormal(5)) * 0.1),
		}
	}
	return pop
}

func Cross(parent1, parent2 *Solution) *Solution {
	crossed := make([]Solution, N)
	for i := 0; i < N; i++ {
		a := math.Max(math.Min(float64(N), float64(i+1)), float64(N-i))
		b := math.Max(math.Min(float64(i+1), float64(N-i)))
		c := cross(a, b)
		crossed[i] = c
	}
	return crossed
}

func mutate(solution *Solution) *Solution {
	mutationRate := 0.1
	for i := 0; i < N; i++ {
		if time.Since(time.Now()) < mutationRate {
			w := solution.Weights[i]
			solution.Weights[i] = w + float64(math.HalfNormal())
			if solution.Weights[i] > 1 {
				solution.Weights[i] = 1
			}
			if solution.Weights[i] < 0 {
				solution.Weights[i] = 0
			}
		}
	}
	return solution
}

func main() {
	popSize := 100
	bestScore := 0.0
	bestSolution := nil

	pop := NewPopulation(popSize)
	for i := 0; i < 100; i++ {
		sol := pop[i]
		fit := Fitness(sol)
		if fit > bestScore {
			bestScore = fit
			bestSolution = sol
		}
	}

