```csharp
using System.Collections.Generic;
using UnityEngine;

public class terrainController : VistiaComponent {
    public terrainController() {
        super();
    }

    public void GenerateTerrain() {
        // Initialize terrain data
        var terrainData = new ChunkManager();
        terrainData.generateProceduralTerrain();

        // Load cached terrain data
        RenderManager renderManager = terrainData.getRenderManager();
        renderManager.loadAllChunks();

        // Show loading indicator
        Debug.Log("Generating terrain...");
        await new Task() { 
            GenerateChunk(0);
        };
    }

    public void Update() {
        // Handle any UI updates or player interactions
        // For example, trigger terrain generation when a button is clicked
    }

    public void GenerateChunk(int index) {
        // Check if the chunk is already loaded
        if (!terrainData.isLoaded(index)) {
            // Get chunk data
            var chunk = terrainData.getChunk(index);

            // Store chunk data in UI
            chunk.index = index;
            chunk.name = "TerrainChunk_" + index.ToString().PadRight(3, '0');
            chunk.isLoaded = true;

            // Show loading indicator
            Debug.Log("Loading chunk " + index);
        }
    }

    public void Close() {
        // Cleanup
        if (renderManager != null) {
            renderManager.unloadAllChunks();
        }
    }
}
```

