    {
        var entities = new List<EntityGeometry>
        {
            new EntityGeometry(new Point(0, 0, 0)),
            new EntityGeometry(new Line(new Point(0, 0, 0), new Point(1, 0, 0))),
            new EntityGeometry(new Face(new Rectangle(new Point(0, 0, 0), new Point(1, 1, 0))))
