        }

        .container {
            width: 400px;
            height: 400px;
            border-radius: 50%;
            position: relative;
            overflow: hidden;
        }

        .sun {
            width: 30px;
            height: 30px;
            background-color: #fff;
            fill: none;
            border-radius: 50%;
            position: absolute;
            left: -50%;
            top: -50%;
        }

        .planet {
            width: 20px;
            height: 20px;
            border-radius: 50%;
            position: absolute;
            left: 0;
            top: 0;
            transition: transform 0.5s;
        }

        .star {
            width: 10px;
            height: 10px;
            background-color: #f0f0f0;
            position: absolute;
            left: 0;
            top: 0;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="sun"></div>
        <div id="planets"></div>
        <div class="stars"></div>
    </div>

    <script>
        const planets = ['Mercury', 'Venus', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune', 'Pluto'];
        const orbits = [
            { radius: 1.5, color: '#00ff00' },
            { radius: 2.5, color: '#ffff00' },
            { radius: 3.5, color: '#0000ff' },
            { radius: 5.5, color: '#00ff00' },
            { radius: 6.5, color: '#ffff00' },
            { radius: 7.5, color: '#0000ff' },
            { radius: 9.5, color: '#00ff00' },
            { radius: 10.5, color: '#ffff00' }
        ];

        let currentTime = 0;
        let lastUpdate = 0;

        function animate() {
            currentTime = Date.now();
            requestAnimationFrame(animate);

            // Calculate planet positions
            const positions = planets.map((planet, index) => {
                const period = orbits[index].radius / (Math.PI * Math.sqrt(2));
                const angle = (period / 2) * (Math.PI * (currentTime / 1000));
                return {
                    x: orbits[index].radius * Math.cos(angle),
                    y: orbits[index].radius * Math.sin(angle)
                };
            });

            // Update planets
            Object.entries(positions).forEach(([x, y]) => {
                const planet = planets.find(p => p.x === x && p.y === y);
                planet.left = x + 50;
                planet.top = y + 50;

                // Animate
                if(currentTime - lastUpdate > 1000) {
                    planet.style.transform = `translate(${planet.left}px, ${planet.top}px)`;
                    lastUpdate = currentTime;
                } else {
                    planet.style.transform = `translate(${planet.left}px, ${planet.top}px) every 1000ms`;
                }
            });

            // Add star movement
            Object.entries(starPositions).forEach(([x, y]) => {
                const planet = planets.find(p => p.x === x && p.y === y);
                planet.left = x + 50;
                planet.top = y + 50;

                planet.style.transform = `translate(${planet.left}px, ${planet.top}px)`;
                requestAnimationFrame(updateStarPositions);
            });

            requestAnimationFrame(animate);
        }

        // Initialize
        const starPositions = orbits.map((orbit, index) => 
            Array(8).fill().map(() => ({
                x: 0,
                y: 0
            }));
        );

        document.getElementById('planets').addEventListener('click', () => {
            const planet = planets[Math.floor(Math.random() * planets.length)];
            planets.splice(Math.floor(Math.random() * planets.length), 1);
            updatePlanetPosition(planet);
        });

        updatePlanetPosition = (planet) => {
            const newPositions = planets.map(p => ({
                ...p,
                x: p.x,
                y: p.y
            }));
            updateStarPositions(newPositions);
            drawPlanets();
        };

        updateStarPositions = (positions) => {
            Object.entries(positions).forEach(([x, y]) => {
                const planet = planets.find(p => p.x === x && p.y === y);
                planet.left = x + 50;
                planet.top = y + 50;
            });
        };

        drawPlanets = () => {
            planets.forEach(p => {
                if(p.color) {
                    const ctx = document.querySelector(`[data-id="${p.id}"]`);
                    ctx.fillStyle = p.color;
                    ctx.beginPath();
                    ctx.arc(p.x + 50, p.y + 50, 20, 0, Math.PI * 2);
                    ctx.fill();
                }
            });
        };
    </script>
